{
  "checklist": {
    "sources": [
      "SEQ_FILE_WAREHOUSE_STOCK",
      "DB2_SRC_ERP_INVENTORY"
    ],
    "joins": {
      "JOIN_WAREHOUSE_ERP": "LeftOuter",
      "LOOKUP_SUPPLIER_INFO": "Inner"
    },
    "branches": {
      "JOIN_WAREHOUSE_ERP": [
        "TRANSFORM_SCD2_INVENTORY",
        "EXCEPTION_UNMATCHED"
      ]
    },
    "computed_cols": [
      "AVAILABLE_QTY",
      "INVENTORY_VALUE",
      "STOCK_STATUS",
      "REORDER_REQUIRED",
      "DAYS_UNTIL_REORDER",
      "RECORD_HASH",
      "SCD_EFF_START_DATE",
      "SCD_EFF_END_DATE",
      "IS_CURRENT_FLAG"
    ],
    "sinks": [
      "BQ_TGT_INVENTORY_DIM",
      "SEQ_FILE_EXCEPTIONS"
    ],
    "exception_sinks": [
      "SEQ_FILE_EXCEPTIONS"
    ]
  },
  "artifactType": "pipeline",
  "config": {
    "stages": [
      {
        "name": "SEQ_FILE_WAREHOUSE_STOCK",
        "type": "batchsource",
        "plugin": {
          "name": "File",
          "type": "batchsource",
          "label": "SEQ_FILE_WAREHOUSE_STOCK",
          "properties": {
            "path": "${SEQ_FILE_WAREHOUSE_STOCK_PATH}",
            "format": "delimited",
            "enableHeader": "true"
          }
        }
      },
      {
        "name": "DB2_SRC_ERP_INVENTORY",
        "type": "batchsource",
        "plugin": {
          "name": "Database",
          "type": "batchsource",
          "label": "DB2_SRC_ERP_INVENTORY",
          "properties": {
            "connectionString": "${ERP_DB2_PROD_URL}",
            "importQuery": "SELECT ITEM_CODE, ITEM_DESC, CATEGORY, SUPPLIER_ID, REORDER_LEVEL, LEAD_TIME_DAYS, IS_ACTIVE, EFF_START_DATE, EFF_END_DATE FROM ERP.ITEM_MASTER WHERE IS_ACTIVE = 'Y'"
          }
        }
      },
      {
        "name": "LOOKUP_SUPPLIER_INFO",
        "type": "transform",
        "plugin": {
          "name": "Joiner",
          "type": "transform",
          "label": "LOOKUP_SUPPLIER_INFO",
          "properties": {
            "joinKeys": "SUPPLIER_ID",
            "joinType": "Inner"
          }
        }
      },
      {
        "name": "JOIN_WAREHOUSE_ERP",
        "type": "transform",
        "plugin": {
          "name": "Joiner",
          "type": "transform",
          "label": "JOIN_WAREHOUSE_ERP",
          "properties": {
            "joinKeys": "ITEM_CODE",
            "joinType": "Outer",
            "requiredInputs": "SEQ_FILE_WAREHOUSE_STOCK"
          }
        }
      },
      {
        "name": "TRANSFORM_SCD2_INVENTORY",
        "type": "transform",
        "plugin": {
          "name": "Wrangler",
          "type": "transform",
          "label": "TRANSFORM_SCD2_INVENTORY",
          "properties": {
            "directives": "set-column AVAILABLE_QTY ON_HAND_QTY - RESERVED_QTY\nset-column INVENTORY_VALUE ON_HAND_QTY * UNIT_COST\nset-column STOCK_STATUS if(AVAILABLE_QTY == 0, 'OUT_OF_STOCK', if(AVAILABLE_QTY < REORDER_LEVEL, 'LOW_STOCK', 'IN_STOCK'))\nset-column REORDER_REQUIRED if(AVAILABLE_QTY < REORDER_LEVEL, 1, 0)\nset-column DAYS_UNTIL_REORDER if(REORDER_REQUIRED == 1, LEAD_TIME_DAYS, -1)\nset-column RECORD_HASH md5(concat(ITEM_CODE, WAREHOUSE_ID, string(ON_HAND_QTY), string(UNIT_COST)))\nset-column SCD_EFF_START_DATE today()"
          }
        }
      },
      {
        "name": "SCD2_WINDOW_PROCESSOR",
        "type": "transform",
        "plugin": {
          "name": "Spark SQL",
          "type": "transform",
          "label": "SCD2_WINDOW_PROCESSOR",
          "properties": {
            "sql": "SELECT *, COALESCE(LEAD(SCD_EFF_START_DATE) OVER(PARTITION BY ITEM_CODE ORDER BY SCD_EFF_START_DATE), CAST('9999-12-31' AS DATE)) AS SCD_EFF_END_DATE, IF(LEAD(SCD_EFF_START_DATE) OVER(PARTITION BY ITEM_CODE ORDER BY SCD_EFF_START_DATE) IS NULL, 1, 0) AS IS_CURRENT_FLAG FROM mytable"
          }
        }
      },
      {
        "name": "SORT_BY_ITEM",
        "type": "transform",
        "plugin": {
          "name": "Sorter",
          "type": "transform",
          "label": "SORT_BY_ITEM",
          "properties": {
            "sortKeys": "ITEM_CODE ASC, WAREHOUSE_ID ASC"
          }
        }
      },
      {
        "name": "BQ_TGT_INVENTORY_DIM",
        "type": "batchsink",
        "plugin": {
          "name": "BigQueryTable",
          "type": "batchsink",
          "label": "BQ_TGT_INVENTORY_DIM",
          "properties": {
            "dataset": "${BQ_DATASET}",
            "table": "inventory_dimension",
            "operation": "MERGE",
            "relationTableKey": "ITEM_CODE"
          }
        }
      },
      {
        "name": "SEQ_FILE_EXCEPTIONS",
        "type": "batchsink",
        "plugin": {
          "name": "File",
          "type": "batchsink",
          "label": "SEQ_FILE_EXCEPTIONS",
          "properties": {
            "path": "${SEQ_FILE_EXCEPTIONS_PATH}",
            "format": "csv"
          }
        }
      }
    ],
    "connections": [
      {
        "from": "SEQ_FILE_WAREHOUSE_STOCK",
        "to": "JOIN_WAREHOUSE_ERP"
      },
      {
        "from": "DB2_SRC_ERP_INVENTORY",
        "to": "LOOKUP_SUPPLIER_INFO"
      },
      {
        "from": "LOOKUP_SUPPLIER_INFO",
        "to": "JOIN_WAREHOUSE_ERP"
      },
      {
        "from": "JOIN_WAREHOUSE_ERP",
        "to": "TRANSFORM_SCD2_INVENTORY"
      },
      {
        "from": "JOIN_WAREHOUSE_ERP",
        "to": "SEQ_FILE_EXCEPTIONS"
      },
      {
        "from": "TRANSFORM_SCD2_INVENTORY",
        "to": "SCD2_WINDOW_PROCESSOR"
      },
      {
        "from": "SCD2_WINDOW_PROCESSOR",
        "to": "SORT_BY_ITEM"
      },
      {
        "from": "SORT_BY_ITEM",
        "to": "BQ_TGT_INVENTORY_DIM"
      }
    ]
  }
}

